  _push(`<div${ssrRenderAttrs(_attrs)}><div style="${ssrRenderStyle({ "display": "none" })}" hidden="true" aria-hidden="true">Are you an LLM? You can read better optimized documentation at /cli/agent.md for this page in Markdown format</div><h1 id="agent-command" tabindex="-1">Agent Command <a class="header-anchor" href="#agent-command" aria-label="Permalink to “Agent Command”">​</a></h1>`);
